('autoclip-studio', 'AutoClip Studio', 'open-source', '["people","dev"]', 'live', '{"en":"Topic in, finished short video out","vi":"Nhập chủ đề, nhận video ngắn hoàn chỉnh"}', '{"en":"Turn a topic, a website or a repo into a finished short video. Claude writes, voices and animates it; you review and publish.","vi":"Biến một chủ đề, một trang web hay một repo thành video ngắn hoàn chỉnh. Claude viết kịch bản, lồng tiếng và dựng hình; bạn chỉ việc duyệt rồi đăng."}', 'https://github.com/openyard-cloud/autoclip-studio', 'https://github.com/openyard-cloud/autoclip-studio', 'MIT', '/logos/autoclip-studio.png', 'tile', '/images/autoclip-studio.webp', '/og/autoclip-studio.png', '#4b2a8a', '["thihodev"]', '["video","ai","creators"]', 1, 1, '{"text":[["Auto","#e8eaee"],["Clip","#ff4d6d"]]}', '2026-11-04', 1793750400000, 1793750400000),
('chatscape', 'Chatscape', 'open-source', '["wild"]', 'live', '{"en":"Living wallpapers for your AI chat","vi":"Hình nền sống động cho khung chat AI"}', '{"en":"Live ASCII and pixel wallpapers behind your AI chat. Twenty animated scenes, no account, nothing leaves your browser.","vi":"Hình nền ASCII và pixel chuyển động phía sau khung chat AI. Hai mươi cảnh, không cần tài khoản, dữ liệu không rời khỏi trình duyệt."}', 'https://chatscape.openyard.cloud', 'https://github.com/openyard-cloud/chatscape', 'MIT', '/logos/chatscape.png', 'tile', '/images/chatscape.webp', '/og/chatscape.png', '#0b4a5a', '["thihodev"]', '["browser-extension","design"]', 1, 1, '{"src":"/logos/chatscape.png"}', '2026-11-04', 1793750400000, 1793750400000),
('farmmind', 'FarmMind', 'app', '["people"]', 'live', '{"en":"AI assistant for Vietnamese farmers","vi":"Trợ lý AI cho nhà nông Việt Nam"}', '{"en":"For livestock and aquaculture farmers: farm records, weather, an AI assistant that answers in plain words, and IoT sensors.","vi":"Dành cho chủ trại chăn nuôi, thủy sản ở Việt Nam: ghi sổ trại, xem thời tiết, hỏi trợ lý AI bằng lời dễ hiểu, kết nối cảm biến IoT."}', 'https://farmmind.openyard.cloud', NULL, NULL, '/logos/farmmind.svg', 'tile', '/images/farmmind.webp', '/og/farmmind.png', '#1d6b4f', '["thihodev"]', '["agriculture","ai","iot"]', 1, 1, '{"src":"/logos/farmmind-mark-dark.svg"}', '2026-11-04', 1793750400000, 1793750400000),
('sovereign-minds', 'Sovereign Minds', 'open-source', '["wild"]', 'live', '{"en":"An open world of nations run by AI","vi":"Thế giới mở nơi các quốc gia do AI cai trị"}', '{"en":"A world where every nation is run by its own AI mind, starting from the stone age. You are the Watcher who judges and decrees.","vi":"Một thế giới nơi mỗi quốc gia do một AI riêng cai trị, khởi đầu từ thời đồ đá. Bạn là Người Quan Sát, phân xử và ban chiếu chỉ."}', 'https://github.com/openyard-cloud/sovereign-minds', 'https://github.com/openyard-cloud/sovereign-minds', 'MIT', '/logos/sovereign-minds.svg', NULL, '/images/sovereign-minds.webp', '/og/sovereign-minds.png', '#22305c', '["thihodev"]', '["simulation","ai","game"]', 1, 1, '{"src":"/logos/sovereign-minds.svg"}', '2026-11-04', 1793750400000, 1793750400000);
